// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        vm.prank(address(this), address(this));
        c = new PoCGame(address(this), 0);
    }

    function _test(uint256 initialLimit, uint256 newAmount) internal {
        vm.assume(initialLimit != newAmount);
        try c.AdjustBetAmounts(initialLimit) {} catch { return; }
        try c.AdjustDifficulty(newAmount) {} catch { return; }
        assertTrue(c.currentDifficulty() == newAmount && c.currentBetLimit() == initialLimit);
    }

    function testFuzz_test(uint256 initialLimit, uint256 newAmount) public {
        _test(initialLimit, newAmount);
    }

    receive() external payable {}
}
